#include "ark/agent.hpp"
#include "ark/serialize.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace ark;using V=arkjson::Value;
static unsigned checks=0;
static void check(bool pass,const std::string& why){++checks;if(!pass)throw std::runtime_error(why);}
static const V& at(const V& v,const char* key){static const V nil;auto p=v.find(key);return p?*p:nil;}
static V json(const char* value){V out;check(arkjson::parse(value,out),"Fixture JSON");return out;}
static V call(AgentSession& s,const char* tool,V args){args.set("expected_revision",V::makeNum(double(s.revision)));const auto result=s.call(tool,args);check(!at(result,"isError").b,result.dump());return at(result,"structuredContent");}
int main(){try{
    AgentSession s;call(s,"doc_apply",json(R"({"commands":[{"op":"param.set","name":"wall","expr":2},{"op":"feature.add","type":"bspline_surface","name":"Skin","p":{"u_degree":1,"v_degree":1},"native":{"poles":[[[0,0,0],[0,20,0]],[[20,0,0],[20,20,0]]]}}]})"));
    const auto before=documentToJson(s.document);const auto revision=s.revision;V args=json(R"({"action":"offset_check","id":"Skin","mode":"thicken","amount":"wall","samples":9})");auto diagnostic=call(s,"surface_control",args);check(at(diagnostic,"candidate_valid").b,"Planar thickness trial must succeed");check(at(diagnostic,"candidate_self_interference_checked").b,"Actual native candidate checked");check(at(diagnostic,"checked_samples").num==81&&at(diagnostic,"undefined_samples").num==0,"Planar sample accounting");check(at(diagnostic,"sampled_min_radius_mm").isNull()&&at(diagnostic,"hotspots").arr.empty(),"Planar curvature must not invent a radius");check(documentToJson(s.document)==before&&s.revision==revision,"Diagnostics preserve complete source");
    args.set("action",V::makeStr("offset_plan"));args.set("source_brep_sha256",at(diagnostic,"source_brep_sha256"));const auto preview=call(s,"surface_control",args);check(at(preview,"valid").b&&at(preview,"candidate_cached").b,"Exact plan retained for review");check(s.revision==revision&&documentToJson(s.document)==before,"Preview is not publication");V apply=V::makeObj();apply.set("candidate_id",at(preview,"candidate_id"));call(s,"doc_apply",apply);check(s.revision==revision+1&&s.document.features.size()==2,"Explicit apply publishes once");const auto measured=call(s,"native_inspect",json(R"({"id":2,"detail":"properties"})"));check(std::abs(at(at(measured,"report"),"volume_mm3").num-800)<1e-6,"Thickness volume independently equals 20x20x2");
    call(s,"doc_undo",V::makeObj());check(s.document.features.size()==1,"Undo preserves original source");V stale=args;stale.set("expected_revision",V::makeNum(double(revision)));check(at(s.call("surface_control",stale),"isError").b,"Stale diagnostic revision rejects");args.set("source_brep_sha256",V::makeStr(std::string(64,'0')));args.set("expected_revision",V::makeNum(double(s.revision)));check(at(s.call("surface_control",args),"isError").b,"Wrong source digest rejects");
    call(s,"doc_apply",json(R"({"commands":[{"op":"feature.add","type":"bspline_surface","name":"Parabolic skin","p":{"u_degree":2,"v_degree":1},"native":{"poles":[[[0,0,0],[0,20,0]],[[10,0,-10],[10,20,-10]],[[20,0,0],[20,20,0]]]}}]})"));args=json(R"({"action":"offset_check","id":"Parabolic skin","mode":"offset","amount":12,"samples":9})");diagnostic=call(s,"surface_control",args);check(std::abs(at(diagnostic,"sampled_min_radius_mm").num-10)<1e-6,"Native D2 curvature agrees with analytic parabolic-cylinder radius10 at centre");check(!at(diagnostic,"hotspots").arr.empty(),"Requested offset magnitude exposes exact sampled risk positions");check(at(at(diagnostic,"hotspots").arr.front(),"point_mm").arr.size()==3,"Risk has an explicit native position");
    args.set("amount",V::makeNum(0));args.set("expected_revision",V::makeNum(double(s.revision)));check(at(s.call("surface_control",args),"isError").b,"Zero thickness rejects");args.set("amount",V::makeNum(2));args.set("samples",V::makeNum(100));check(at(s.call("surface_control",args),"isError").b,"Unbounded sample request rejects");
    std::string error;Document reopened;check(documentFromJson(documentToJson(s.document),reopened,&error),error);check(reopened.features.size()==s.document.features.size(),"Existing offset/surface serialization retained");std::cout<<checks<<" surface offset diagnostic checks passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
